             end;
             if on(26,16) then begin
                Print(15,' 여기는 인간과 드래곤의 중간 종족이며  혼란');
                Print(15,'스런 세상을 피해 은둔하고있는 Draconian이란');
                Print(15,'자가 살고있는 피라밋이었다.');
                PressAnyKey;
                if party.etc[16] and bit2 > 0 then begin
                   message(7,' 그러나, 아무도 살고 있지 않았다.');
