                end;
                if party.etc[5] = 0 then begin
                   Print(7,' 나는 Draconian이라고 하오. 이런곳까지 사람');
                   Print(7,'이 찾아오리라고는 생각하지 못했는데 참 의외');
                   Print(7,'로군요. 나는 숨어 지내는 오랜 세월동안에 여');
                   Print(7,'러가지 학문을 연구하고 있었소.  특히 천문학');
                   Print(7,'에 대해서는 특별히 전염하여 다루었소.  내가');
                   Print(7,'그동안 알아낸 지식들은 다음과 같은 것이오.');
                   Print(7,' 지금 우리가 살고있는 지구는 태양계에서  세');
                   Print(7,'번째로 위치한 행성인데 이상하게도 위성인 달');
                   Print(7,'이 지구보다도 더 오래되었다는 사실이 연구되');
                   Print(7,'었소. 또한 이 지구가 세차운동에 의해 2 등성');
                   Print(7,'이었던 북극성이 다른 별로 바뀐다는걸 알았소');
                   Print(7,' 물리학에서 알아낸것은, 중수반응에서 매질의');
                   Print(7,'차이로 빛이 속도가 느려진 틈을 이용해 빛 보');
                   Print(7,'다 빠른 입자가 생겨났소. 하지만 절대적인 빛');
                   Print(7,'의 속도에는 미치지 못했지만 말이오.  이것을');
                   Print(7,'잘만 이용하면 미래로의 타임머신이  가능하다');
                   Print(7,'는 걸 입증할 수가 있소.');
                   Print(7,' 사실 이런것은 당신에게는 별 의미가 없는 것');
                   Print(7,'일지도 모르오. 하지만 마지막으로 알아낸것은');
                   Print(7,'바로 당신이 응징하고자 하는  Necromancer 의');
                   Print(7,'출처에 관한 것이오. 당신은 시그너스 X1과 같');
                   Print(7,'은 블랙홀에 대해서 알고있을 것이오. 이런 물');
                   Print(7,'리학적인 파라독스에 의해 그는 생겨났던것이오.');
                   PressAnyKey;
                   Print(7,' 지금 우리가 있는 3차원 위에 또 다른 차원이');
                   Print(7,'있다고 생각하오?  생각은 하더라도 눈으로 확');
                   Print(7,'인은 못해봤을것이오. 우리는 2차원을 인식 할');
                   Print(7,'수가 있소.  하지만 실제로 2차원에  살고있는');
                   Print(7,'생물은 자신의 차원은 인식해도 우리가 살고있');
                   Print(7,'는 3차원은 인식할 수가 없는 것이오. 그의 차');
                   Print(7,'원에는 우리의 차원이  존재하지 않기  때문에');
                   Print(7,'개념을 잡을수가 없는 것이오.  마찬가지로 우');
                   Print(7,'리 또한 지금의 차원보다 한 차원 높은 4 차원');
                   Print(7,'을 개념을 잡기가 어려운 것이오.');
                   Print(7,' 어떤이는 4차원은 시간의 축이 보태어 진다고');
                   Print(7,'하는 이론을 세우더군요.  하지만 나의 이론은');
                   Print(7,'시간은 모든 차원의 기준이며 4차원에 국한 되');
                   Print(7,'지는 않는다는 생각이오. 3차원에서는 동 시간');
                   Print(7,'대에 무한한 2차원을 포함 하듯이 4차원에서는');
                   Print(7,'동 시간대에  무한한 3차원을 포함하고 있다는');
                   Print(7,'이론이 성립되오. 말이 조금은 빗나갔지만  이');
                   Print(7,'이론으로 Necromancer의 출처를 해명해 보겠소');
                   Print(7,' 방금 말했듯이 3차원은 이 공간만이 존재하는');
                   Print(7,'것은 아니오. 동 시대를 살아가는 다른 공간도');
                   Print(7,'인정해야 한다는 말이오.  그 공간들을 이어주');
                   Print(7,'는 것이 바로 블랙 홀이란 것이지요.  그는 원');
                   Print(7,'래 그가 있던 공간에서 블랙 홀을 통해서 다른');
                   Print(7,'공간으로 가려고 시도를 했고 웜 홀을 통해 시');
                   Print(7,'공간을 가로질러 오래전 우리의 공간에 화이트');
                   Print(7,'홀이 생기는 틈을 이용하여 내려왔던 것이오.');
                   Print(7,' 하지만 3차원에 사는 나로서는 그가 전에  있');
                   Print(7,'던 공간에서 왜 이쪽으로 왔는지  알수가 없었');
                   Print(7,'지요. 그래서 그와 같이 이 공간으로 들어왔던');
                   Print(7,'심복들을 통해 그 사정을 알게 되었소.');
                   Print(7,' Necromacer는 저쪽의 공간에서도 지금과 마찬');
                   Print(7,'가지로 차원을 통해 그 공간에 도달했소. 역시');
                   Print(7,'거기서도 악을 뿌리며 거기의 생명체들을 위협');
                   Print(7,'했소. 하지만 어떤 선택되어진 6인의 용사들에');
                   Print(7,'의해 쫒겨나서 여기로 온것이오.  지금의 당신');
                   Print(7,'들과 비슷하다고 생각되지 않소? 그렇소. 다른');
                   Print(7,'공간의 당신들에게 쫒겨난후 다시 여기서 당신');
                   Print(7,'들을 또 만나게 된것이오. Necromancer와 당신');
                   Print(7,'들의 운명은 언제까지나 쫒고 쫒기며 대립하여');
                   Print(7,'야하는 운명으로 탄생되었던 것이오. 이런  이');
                   Print(7,'유에서 당신은 그를 반드시 무찌를 수가  있다');
                   Print(7,'는 근거가 되는 것이오.');
                   Print(7,' 당신들의 건투를 빌어주겠소.');
                   talk('');
                end
                else begin
                   Print(7,' 나의 운명을 생각해 보니  나 역시  당신들을');
                   Print(7,'필연적으로 만나 Necromancer를 물리쳐야 한다');
                   Print(7,'는걸 깨닭았소. 당신들 일행의 제일 뒤에서 도');
                   Print(7,'와주고 싶소. 어떻소.');
                   m[0] := '';
                   m[1] := '저도 바라던 차입니다';
                   m[2] := '별로 좋지는 않군요';
                   k := select(140,2,2,FALSE,TRUE);
                   if k = 0 then exit;
