                   end;
                   if k = 2 then begin
                      Print(7,' 다시 생각해보니 나는 당신들과 같이 싸울 운');
                      Print(7,'명이 아닌것 같소.');
                      PressAnyKey;
                   end;
                end;
             end;
             if on(20,39) then begin
                if party.etc[16] and bit1 > 0 then begin
                   x := 46; y := 41;
                   scroll(TRUE);
