                Print(7,'육신은 없는 영이오. 당신은 Lord Ahn 을 만나');
                Print(7,'보았겠군요. 그리고 우리들의 운명적인 만남도');
                Print(7,'역시 예시 받았겠군요.');
                Print(7,' 사실이야 어떻든 당신에게 이 대륙에서의  할');
                Print(7,'일을 말해 주겠소.');
                PressAnyKey;
                x := 48; y := 57;
                scroll(FALSE);
                Print(7,' 여기는 EVIL GOD 라는 동굴이오. 여기의 보스');
                Print(7,'는 Crab God인데 적 자체는 별거 아니지만  떼');
                Print(7,'를 지어서 다니기 때문에 약간의 애를 먹을 것');
                Print(7,'이오. 7갈래의 길중에서 한곳에 봉인이 숨겨져');
                Print(7,'있을 것이오.');
                PressAnyKey;
                x := 82; y := 16;
                scroll(FALSE);
                Print(7,' 여기는 Muddy 라는 동굴이오.  여기의 보스는');
                Print(7,'Astral Mud라는 자인데  그리 실력이 있다고는');
                Print(7,'볼수가 없소. 다만 동굴 자체가 어려운 미로라');
                Print(7,'는 것과 시야가 좁아지는 불편등은 감수해야만');
                Print(7,'할 것이오. 그리고 마지막에 3마리의 Dragon과');
                Print(7,'7마리의 Mud-Man을 거쳐야만 그가 나타나기 때');
                Print(7,'문에 약간 까다로울 것이오.');
                PressAnyKey;
                x := 16; y := 15;
                soundon := aux;
                scroll(TRUE);
                Print(7,' 여기는 이 대륙의 외진곳이오. 여기서는 어떤');
                Print(7,'만남이 기다리고 있을 것이오.');
                PressAnyKey;
                party.etc[16] := party.etc[16] or bit1;
             end;
          end

